        "description": "<div style=\"line-height: 1.7;\"><p style=\"margin-bottom: 12px;\"><b>กลุ่มคืออะไร?</b></p><p style=\"margin-bottom: 12px;\">กลุ่มเป็นแนวคิดหลักของ OneAPI คล้ายกับ \"แพ็กเกจบริการ\":</p><ul style=\"margin-left: 20px; margin-bottom: 12px; font-size: 13px;\"><li>🎯 แต่ละกลุ่มสามารถมีหลายบัญชีต้นทาง</li><li>💰 แต่ละกลุ่มมีตัวคูณการเรียกเก็บเงินอิสระ</li><li>👥 สามารถตั้งค่าเป็นสาธารณะหรือเฉพาะกลุ่มได้</li></ul><p style=\"margin-top: 12px; padding: 8px 12px; background: #f0fdf4; border-left: 3px solid #10b981; border-radius: 4px; font-size: 13px;\"><b>💡 ตัวอย่าง:</b> คุณสามารถสร้างกลุ่ม \"VIP Premium\" (อัตราสูง) และ \"Free Trial\" (อัตราต่ำ)</p><p style=\"margin-top: 16px; color: #10b981; font-weight: 600;\">👉 คลิก \"การจัดการกลุ่ม\" ในแถบด้านซ้าย</p></div>"
