        "description": "<div style=\"line-height: 1.7;\"><p style=\"margin-bottom: 12px;\">ตั้งค่าลําดับความสําคัญของการโทรบัญชี</p> <div style=\"padding: 8px 12px; พื้นหลัง: #eff6ff; ขอบซ้าย: 3px #3b82f6 ทึบ; รัศมีขอบ: 4px; ขนาดตัวอักษร: 13px; ขอบล่าง: 12px;\"> <b>📊 กฎลําดับความสําคัญ:</b><ul style=\"margin: 8px 0 0 16px;\"><li>จํานวนต่ํา = ลําดับความสําคัญสูงกว่า</li><li>ระบบใช้บัญชีมูลค่าต่ําก่อน</li><li>ลําดับความสําคัญเดียวกัน = เลือกแบบสุ่ม</li></ul></div><p style=\"padding: 8px 12px; พื้นหลัง: #f0fdf4; ขอบซ้าย: 3px #10b981 ทึบ; รัศมีขอบ: 4px; ขนาดตัวอักษร: 13px;\"> <b>💡 กรณีการใช้งาน:</b> ตั้งค่าบัญชีหลักเป็นค่าต่ําลง, บัญชีสํารองเป็นค่าสูงขึ้น</p></div>",
        "nextBtn": "ถัดไป"
