        "description": "<div style=\"line-height: 1.7;\"><p style=\"margin-bottom: 12px;\">System จะสร้าง API Key ครบถ้วนหลังจากคลิกสร้าง</p> <div style=\"padding: 8px 12px; พื้นหลัง: #fee2e2; ขอบซ้าย: 3px #ef4444 ทึบ; รัศมีขอบ: 4px; ขนาดตัวอักษร: 13px; ขอบล่าง: 12px;\"> <b>⚠️ เตือนความจําสําคัญ:</b><ul style=\"margin: 8px 0 0 16px;\"><li>คีย์จะแสดงเพียงครั้งเดียว คัดลอกทันที</li><li>ต้องสร้างใหม่หากสูญหาย</li><li>เก็บให้ปลอดภัย อย่าแชร์กับผู้อื่น</li></ul></div><div style=\"padding: 8px 12px; พื้นหลัง: #f0fdf4; ขอบซ้าย: 3px #10b981 ทึบ; ขอบรัศมี: 4px; ขนาดตัวอักษร: 13px; ขอบล่าง: 12px;\"> <b>🚀 ขั้นตอนถัดไป:</b><ul style=\"margin: 8px 0 0 16px;\"><li>คัดลอกคีย์ sk-xxx ที่สร้างขึ้น</li><li>ใช้ในไคลเอนต์ที่รองรับ OpenAI</li> ใด ๆ <li>เริ่มสัมผัสบริการ AI!</li></ul></div> <p style=\"ขอบด้านบน: 12px; สี: #10b981; น้ําหนักตัวอักษร: 600;\"> 👉 คลิกปุ่ม \"สร้าง\"</p></div>"
